const A=3,C=0.5,K=0.8,R=0.12,N=40,S=3;
const L=(x,z)=>0.5*(A*x*x+C*z*z);
const rnd=n=>{const s=Math.sin(n*12.9898+78.233)*43758.5453;return s-Math.floor(s);};
const gs=n=>Math.sqrt(-2*Math.log(Math.max(1e-9,rnd(n))))*Math.cos(6.2832*rnd(n+0.5));
function sv(s,i){const b=+i.batchSize,sd=b>=256?0:2/Math.sqrt(b),k=s.run*997+s.step*2+1;return [i.learningRate*(-A*s.x+sd*gs(k)),i.learningRate*(-C*s.z+sd*gs(k+0.25))];}
function adv(s,i){if(s.status>=2)return s;const d=sv(s,i),x=s.x+d[0],z=s.z+d[1],st=s.step+1,status=L(x,z)>3?3:st>=N?2:1;return {...s,x,z,step:st,trail:s.trail.concat([[x,z]]),status,on:status===1&&s.on};}
export function initialState(){return {x:0.7,z:2.2,sx:0.7,sz:2.2,step:0,trail:[],saved:[],status:0,run:0,on:false};}
export function reduce({state:s,event:e,inputs:i}){
if(e.type==='step'){if(!s.on||e.tick%6)return s;return adv(s,i);}
if(e.type==='action'){const a=e.action;
if(a==='stepOnce')return adv({...s,on:false},i);
if(a==='run')return s.status>=2?s:{...s,on:!s.on};
if(a==='savePath')return {...s,saved:s.trail,x:s.sx,z:s.sz,trail:[],step:0,status:0,on:false,run:s.run+1};
if(a==='clearTrail')return {...s,trail:[],step:0,status:0,on:false,sx:s.x,sz:s.z};}
if((e.type==='drag_move'||e.type==='drag_end')&&s.step===0){const x=Math.max(-1,Math.min(1,e.value));return {...s,x,sx:x};}
return s;}
const q=(dx,dz)=>{const l=Math.hypot(dx,dz),h=0.70711;return [dz/l*h,0,-dx/l*h,h];};
const P=(p,o)=>[p[0],K*L(p[0],p[1])+o,p[1]];
function arr(d,y,s,show){const l=Math.hypot(d[0],d[1]);if(!show||l<1e-6)return {visible:false};return {visible:true,position:[s.x+d[0]/l*R,y,s.z+d[1]/l*R],quaternion:q(d[0],d[1]),scale:[1,S*l,1]};}
export function evaluate({inputs:i,state:s}){
const n={},by=K*L(s.x,s.z)+R,live=s.status<2;
n.ball={position:[s.x,by,s.z]};
n.st={text:['Ready','Running','Finished','Diverged'][s.status]};
const d=sv(s,i),lr=i.learningRate;
n.sa=arr(d,by,s,live);
n.ga=arr([-lr*A*s.x,-lr*C*s.z],by,s,live&&i.showTrueGradient);
for(let j=0;j<N;j++){const a=s.trail[j],b=s.saved[j];n['a'+j]=a?{visible:true,position:P(a,0.04)}:{visible:false};n['b'+j]=b?{visible:true,position:P(b,0.04)}:{visible:false};}
return {nodes:n,readouts:{loss:L(s.x,s.z),stepNo:s.step,dist:Math.hypot(s.x,s.z),status:s.status}};}
